  public IElementType advance() throws java.io.IOException
  {
    int zzInput;
    int zzAction;

    // cached fields:
    int zzCurrentPosL;
    int zzMarkedPosL;
    int zzEndReadL = zzEndRead;
    CharSequence zzBufferL = zzBuffer;

    int [] zzTransL = ZZ_TRANS;
    int [] zzRowMapL = ZZ_ROWMAP;
    int [] zzAttrL = ZZ_ATTRIBUTE;

    while (true) {
      zzMarkedPosL = zzMarkedPos;

      zzAction = -1;

      zzCurrentPosL = zzCurrentPos = zzStartRead = zzMarkedPosL;

      zzState = ZZ_LEXSTATE[zzLexicalState];

      // set up zzAction for empty match case:
      int zzAttributes = zzAttrL[zzState];
      if ( (zzAttributes & 1) == 1 ) {
        zzAction = zzState;
      }


      zzForAction: {
        while (true) {

          if (zzCurrentPosL < zzEndReadL) {
            zzInput = Character.codePointAt(zzBufferL, zzCurrentPosL);
            zzCurrentPosL += Character.charCount(zzInput);
          }
          else if (zzAtEOF) {
            zzInput = YYEOF;
            break zzForAction;
          }
          else {
            // store back cached positions
            zzCurrentPos  = zzCurrentPosL;
            zzMarkedPos   = zzMarkedPosL;
            boolean eof = zzRefill();
            // get translated positions and possibly new buffer
            zzCurrentPosL  = zzCurrentPos;
            zzMarkedPosL   = zzMarkedPos;
            zzBufferL      = zzBuffer;
            zzEndReadL     = zzEndRead;
            if (eof) {
              zzInput = YYEOF;
              break zzForAction;
            }
            else {
              zzInput = Character.codePointAt(zzBufferL, zzCurrentPosL);
              zzCurrentPosL += Character.charCount(zzInput);
            }
          }
          int zzNext = zzTransL[ zzRowMapL[zzState] + zzCMap(zzInput) ];
          if (zzNext == -1) break zzForAction;
          zzState = zzNext;

          zzAttributes = zzAttrL[zzState];
          if ( (zzAttributes & 1) == 1 ) {
            zzAction = zzState;
            zzMarkedPosL = zzCurrentPosL;
            if ( (zzAttributes & 8) == 8 ) break zzForAction;
          }

        }
      }

      // store back cached position
      zzMarkedPos = zzMarkedPosL;

      if (zzInput == YYEOF && zzStartRead == zzCurrentPos) {
        zzAtEOF = true;
        return null;
      }
      else {
        switch (zzAction < 0 ? zzAction : ZZ_ACTION[zzAction]) {
          case 1:
            { return BAD_CHARACTER;
            }
          // fall through
          case 39: break;
          case 2:
            { return WHITE_SPACE;
            }
          // fall through
          case 40: break;
          case 3:
            { return HASH;
            }
          // fall through
          case 41: break;
          case 4:
            { return LPAREN;
            }
          // fall through
          case 42: break;
          case 5:
            { return RPAREN;
            }
          // fall through
          case 43: break;
          case 6:
            { return COMMA;
            }
          // fall through
          case 44: break;
          case 7:
            { return DOT;
            }
          // fall through
          case 45: break;
          case 8:
            { return NUMBER;
            }
          // fall through
          case 46: break;
          case 9:
            { return SEMICOLON;
            }
          // fall through
          case 47: break;
          case 10:
            { return EQ;
            }
          // fall through
          case 48: break;
          case 11:
            { return AT;
            }
          // fall through
          case 49: break;
          case 12:
            { return IDENTIFIER;
            }
          // fall through
          case 50: break;
          case 13:
            { return LBRACKET;
            }
          // fall through
          case 51: break;
          case 14:
            { return RBRACKET;
            }
          // fall through
          case 52: break;
          case 15:
            { return LBRACE;
            }
          // fall through
          case 53: break;
          case 16:
            { return RBRACE;
            }
          // fall through
          case 54: break;
          case 17:
            { yybegin(AFTER_RULE_PARAMS);
		return RPAREN;
            }
          // fall through
          case 55: break;
          case 18:
            { ruleBraceDepth = 1;
		yybegin(IN_RULE_BODY);
		return LBRACE;
            }
          // fall through
          case 56: break;
          case 19:
            { return RULE_BODY_CONTENT;
            }
          // fall through
          case 57: break;
          case 20:
            { ruleBraceDepth++;
		return RULE_BODY_CONTENT;
            }
          // fall through
          case 58: break;
          case 21:
            { ruleBraceDepth--;
		if (ruleBraceDepth == 0) {
			yybegin(YYINITIAL);
      return RBRACE;
    }
		return RULE_BODY_CONTENT;
            }
          // fall through
          case 59: break;
          case 22:
            { return STRING;
            }
          // fall through
          case 60: break;
          case 23:
            { return LINE_COMMENT;
            }
          // fall through
          case 61: break;
          case 24:
            { return IN;
            }
          // fall through
          case 62: break;
          case 25:
            { return OR;
            }
          // fall through
          case 63: break;
          case 26:
            { return AND;
            }
          // fall through
          case 64: break;
          case 27:
            { return NOT;
            }
          // fall through
          case 65: break;
          case 28:
            { return BLOCK_COMMENT;
            }
          // fall through
          case 66: break;
          case 29:
            { yybegin(RULE_PARAMS);
    return RULE;
            }
          // fall through
          case 67: break;
          case 30:
            { return ACTION;
            }
          // fall through
          case 68: break;
          case 31:
            { return TYPE_DOUBLE;
            }
          // fall through
          case 69: break;
          case 32:
            { return ENTITY;
            }
          // fall through
          case 70: break;
          case 33:
            { return TYPE_STRING;
            }
          // fall through
          case 71: break;
          case 34:
            { return TYPE_BOOLEAN;
            }
          // fall through
          case 72: break;
          case 35:
            { return TYPE_INTEGER;
            }
          // fall through
          case 73: break;
          case 36:
            { return RELATION;
            }
          // fall through
          case 74: break;
          case 37:
            { return ATTRIBUTE;
            }
          // fall through
          case 75: break;
          case 38:
            { return PERMISSION;
            }
          // fall through
          case 76: break;
          default:
            zzScanError(ZZ_NO_MATCH);
          }
      }
    }
  }


